/// One row of Raven's `cvarTable` of `ui_main.c`, the `cvarTable_t` record with the cvar handle as a key path into `UIStorage`.
/// A nil key path is Raven's NULL handle, a cvar the module registers and never reads.
struct CvarTableRow {
    let vmCvar: KeyPath<UIStorage, JKAMP.VmCvar>?
    let cvarName: String
    let defaultString: String
    let cvarFlags: Int32
}

/// The one instance. `vmMain` has no context argument and the engine calls the module from one thread, so this is not isolated.
public nonisolated(unsafe) var world = UIWorld()

/// The string pool of rule 9, the only source of a runtime `char *`.
var strings: StringPool { world.strings }
